cypher_first_attempt:
MATCH (g:Gene)-[:GENEHASMOLECULARFUNCTION]->(mf:MolecularFunction)
WHERE g.geneSymbol = 'GPR84'
RETURN g.geneSymbol AS gene, mf.commonName AS molecular_function, mf.xrefGeneOntology AS go_id, mf.nodeID AS mf_id;

